import numpy as np

def f(x, y):
    return 3*(x**2 + y**2) + 15*(x**2 * y**2) - (4*x*y + 1)**2

def check_n(n, a):
    for i in range(n):
        for j in range(i + 1, n):
            if f(a[i], a[j]) < 0:
                return False
    return True

# We want to find if there exist a_1, ..., a_n such that f(a_i, a_j) >= 0 for all i < j.
# Let's try to optimize this.
# For a fixed n, we want to find a_1, ..., a_n to maximize min_{i<j} f(a_i, a_j).

from scipy.optimize import minimize

def objective(a):
    n = len(a)
    min_f = float('inf')
    for i in range(n):
        for j in range(i + 1, n):
            val = f(a[i], a[j])
            if val < min_f:
                min_f = val
    return -min_f

for n in range(2, 6):
    print(f"Testing n={n}")
    # Try different starting points
    found = False
    for start_a in [[10.0, 0.1] * (n//2 + 1), [1.0, 0.5] * (n//2 + 1), [100.0, 0.01] * (n//2 + 1), [0.5, 1.5] * (n//2 + 1)]:
        res = minimize(objective, np.array(start_a[:n]), bounds=[(1e-6, None)]*n)
        if res.success and -res.fun >= -1e-7:
            print(f"  Found solution for n={n}: {res.x}, min_f={-res.fun}")
            found = True
            break
