def f(x, y):
    return 3*(x**2 + y**2) + 15*(x**2 * y**2) - (4*x*y + 1)**2

def objective(a):
    n = len(a)
    if n < 2: return 0
    min_f = float('inf')
    for i in range(n):
        for j in range(i + 1, n):
            val = f(a[i], a[j])
            if val < min_f:
                min_f = val
    return -min_f

for m in range(1, 6):
    print(f"Testing m={m}")
    found = False
    for attempt in range(10):
        start_a = np.random.uniform(0.0001, 1.732, m)
        res = minimize(objective, start_a, bounds=[(1e-6, 1.732)]*m)
        if res.success and -res.fun >= -1e-7:
            print(f"  Found m={m}: {res.x}, min_f={-res.fun}")
